CREATE TABLE generation_jobs(id VARCHAR2(36) PRIMARY KEY,owner_id VARCHAR2(36) NOT NULL,trip_id VARCHAR2(36) NOT NULL,status VARCHAR2(20) NOT NULL CHECK(status IN ('QUEUED','RUNNING','SUCCEEDED','FAILED')),input_json CLOB NOT NULL,output_json CLOB,error_code VARCHAR2(80),created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,updated_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL);
CREATE INDEX jobs_status ON generation_jobs(status,created_at);
CREATE TABLE conversations(id VARCHAR2(36) PRIMARY KEY,owner_id VARCHAR2(36) NOT NULL,created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE guide_messages(id VARCHAR2(36) PRIMARY KEY,conversation_id VARCHAR2(36) NOT NULL REFERENCES conversations(id),role VARCHAR2(20) NOT NULL,content CLOB NOT NULL,created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL);
CREATE INDEX messages_conversation ON guide_messages(conversation_id,created_at);
CREATE TABLE saved_phrases(id VARCHAR2(36) PRIMARY KEY,owner_id VARCHAR2(36) NOT NULL,content CLOB NOT NULL,created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL);
